const PORTAL_CONFIG = Object.freeze({
  dataSheet: 'Data_Source',
  indexSheet: 'Index',
  dataRows: 500,
  dataFormatRows: 100,
  dataColumns: 6,
  spreadsheetProperty: 'PGE_PORTAL_SPREADSHEET_ID',
  protectionPrefix: 'PGE Portal - ',

  departments: ['All', 'Finance', 'Sales', 'HR', 'Operations'],
  statuses: ['All', 'Active', 'Pending', 'Archived'],

  departmentLabels: {
    All: 'Semua',
    Finance: 'Keuangan',
    Sales: 'Penjualan',
    HR: 'SDM',
    Operations: 'Operasional'
  },

  statusLabels: {
    All: 'Semua',
    Active: 'Aktif',
    Pending: 'Menunggu',
    Archived: 'Arsip'
  },

  colors: {
    accent: '#0F766E',
    accentDark: '#115E59',
    surface: '#FFFFFF',
    mutedSurface: '#F8FAFC',
    text: '#0F172A',
    muted: '#64748B',
    border: '#E2E8F0',
    successBackground: '#ECFDF5',
    successText: '#047857',
    pendingBackground: '#FFFBEB',
    pendingText: '#B45309',
    archivedBackground: '#F1F5F9',
    archivedText: '#64748B'
  }
});

function onOpen() {
  SpreadsheetApp.getUi()
    .createMenu('PGE Portal')
    .addItem('Siapkan Web Portal', 'setupWebPortal')
    .addItem('Buka Web Portal', 'openWebPortal')
    .addSeparator()
    .addItem('Tampilkan Data_Source', 'showDataSource')
    .addItem('Sembunyikan Data_Source', 'hideDataSource')
    .addSeparator()
    .addItem('Lindungi Data_Source', 'enablePortalProtection')
    .addItem('Buka Perlindungan', 'disablePortalProtection')
    .addToUi();
}

/**
 * Run once from the bound spreadsheet before deploying the web app.
 * Stores the spreadsheet ID so the deployed web app can reliably open it.
 */
function setupWebPortal() {
  const spreadsheet = SpreadsheetApp.getActiveSpreadsheet();
  if (!spreadsheet) {
    throw new Error('Buka Apps Script dari spreadsheet portal, lalu jalankan setupWebPortal().');
  }

  const lock = LockService.getDocumentLock();
  if (!lock.tryLock(5000)) {
    throw new Error('Portal sedang dipakai. Coba lagi beberapa detik lagi.');
  }

  try {
    PropertiesService.getScriptProperties()
      .setProperty(PORTAL_CONFIG.spreadsheetProperty, spreadsheet.getId());

    const dataSheet = getOrCreateSheet_(spreadsheet, PORTAL_CONFIG.dataSheet, false);
    prepareDataSource_(dataSheet);
    prepareLauncherSheet_(spreadsheet);
    applyPortalProtections_(dataSheet);

    dataSheet.hideSheet();
    spreadsheet.getSheetByName(PORTAL_CONFIG.indexSheet).activate();

    const webAppUrl = ScriptApp.getService().getUrl() || '';
    spreadsheet.toast(
      webAppUrl
        ? 'Backend siap. Web app juga sudah memiliki URL deployment.'
        : 'Backend siap. Selanjutnya Deploy > New deployment > Web app.',
      'PGE Portal',
      7
    );

    return {
      spreadsheetId: spreadsheet.getId(),
      webAppUrl: webAppUrl
    };
  } finally {
    lock.releaseLock();
  }
}

// Compatibility with previous versions.
function setupLandingPortal() {
  return setupWebPortal();
}

function setupCompanyPortal() {
  return setupWebPortal();
}

function doGet() {
  const template = HtmlService.createTemplateFromFile('Index');
  return template.evaluate()
    .setTitle('PGE Company Portal')
    .addMetaTag('viewport', 'width=device-width, initial-scale=1');
}

function getPortalLogoUri_() {
  return "data:image/png;base64,";
}

function include_(filename) {
  return HtmlService.createHtmlOutputFromFile(filename).getContent();
}

/**
 * Main data contract consumed by the web frontend.
 */
function getPortalBootstrap() {
  const spreadsheet = getPortalSpreadsheet_();
  const dataSheet = spreadsheet.getSheetByName(PORTAL_CONFIG.dataSheet);

  if (!dataSheet) {
    throw new Error('Data_Source belum tersedia. Jalankan setupWebPortal() dari spreadsheet.');
  }

  assertDataSourceSchema_(dataSheet);

  const records = getPortalRecords_(dataSheet).sort(compareRecords_);
  const departments = getDepartmentValues_(dataSheet);

  return {
    company: 'CV Pusat Grosir Eceran',
    appName: 'PGE Company Portal',
    currentUser: Session.getActiveUser().getEmail() || '',
    records: records,
    departments: departments.map(value => ({
      value: value,
      label: getDepartmentLabel_(value)
    })),
    statuses: PORTAL_CONFIG.statuses.map(value => ({
      value: value,
      label: getStatusLabel_(value)
    })),
    stats: buildStatsPayload_(records, departments),
    canManage: dataSheet.getRange(1, 1).canEdit(),
    logoUri: getPortalLogoUri_(),
    generatedAt: new Date().toISOString()
  };
}

function refreshPortal() {
  return getPortalBootstrap();
}

/**
 * Saves an existing link or creates a blank Google Sheet.
 * Data_Source remains the single source of truth.
 */
function savePortalResource(formData) {
  const spreadsheet = getPortalSpreadsheet_();
  const lock = LockService.getScriptLock();

  if (!lock.tryLock(8000)) {
    throw new Error('Portal sedang menyimpan data lain. Coba lagi beberapa detik.');
  }

  try {
    if (!formData || typeof formData !== 'object') {
      throw new Error('Isian formulir tidak terbaca. Muat ulang halaman lalu coba lagi.');
    }

    const dataSheet = spreadsheet.getSheetByName(PORTAL_CONFIG.dataSheet);
    if (!dataSheet) {
      throw new Error('Data_Source belum tersedia. Jalankan setupWebPortal().');
    }

    assertDataSourceSchema_(dataSheet);

    const isEdit = String(formData.mode || '').trim() === 'edit';
    const departmentChoice = String(formData.department || '').trim();
    const newDepartment = String(formData.newDepartment || '').trim();
    const resourceName = String(formData.resourceName || '').trim();
    const description = String(formData.description || '').trim();
    const status = String(formData.status || '').trim();
    const ownerEmail = String(formData.ownerEmail || '').trim();
    const linkMode = String(formData.linkMode || 'existing').trim();
    let targetUrl = String(formData.targetUrl || '').trim();
    const originalRow = parseInt(formData.editRow, 10);
    const originalName = String(formData.editOriginalName || '').trim();

    const existingDepartments = getDepartmentValues_(dataSheet);
    let department = departmentChoice;

    if (departmentChoice === '__NEW__') {
      if (!newDepartment) throw new Error('Nama divisi baru wajib diisi.');
      if (/^(all|semua)$/i.test(newDepartment)) {
        throw new Error('Nama divisi tidak boleh memakai kata All atau Semua.');
      }

      const duplicate = existingDepartments.find(item =>
        item.toLowerCase() === newDepartment.toLowerCase() ||
        getDepartmentLabel_(item).toLowerCase() === newDepartment.toLowerCase()
      );

      if (duplicate) {
        throw new Error('Divisi tersebut sudah ada. Pilih ' + getDepartmentLabel_(duplicate) + '.');
      }

      department = newDepartment;
    } else if (!existingDepartments.includes(departmentChoice)) {
      throw new Error('Divisi yang dipilih tidak ditemukan. Muat ulang portal.');
    }

    if (!resourceName) throw new Error('Nama file wajib diisi.');
    if (!description) throw new Error('Kegunaan file wajib diisi.');
    if (!PORTAL_CONFIG.statuses.slice(1).includes(status)) {
      throw new Error('Status yang dipilih tidak sesuai.');
    }
    if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(ownerEmail)) {
      throw new Error('Email penanggung jawab belum sesuai.');
    }

    if (department.length > 60) throw new Error('Nama divisi maksimal 60 karakter.');
    if (resourceName.length > 120) throw new Error('Nama file maksimal 120 karakter.');
    if (description.length > 500) throw new Error('Kegunaan file maksimal 500 karakter.');

    if (!dataSheet.getRange(1, 1).canEdit()) {
      throw new Error('Akun ini hanya memiliki akses baca. Minta akses Editor untuk mengubah file.');
    }

    let targetRow = 0;

    if (isEdit) {
      if (originalRow >= 2 && originalRow <= dataSheet.getLastRow()) {
        targetRow = originalRow;
      } else {
        const lastRow = dataSheet.getLastRow();
        const names = dataSheet.getRange(2, 2, lastRow - 1, 1).getDisplayValues().flat();
        const foundIndex = names.findIndex(n => n.trim() === originalName);
        if (foundIndex !== -1) {
          targetRow = foundIndex + 2;
        } else {
          throw new Error('Dokumen yang akan diedit tidak ditemukan di Data_Source.');
        }
      }
    } else {
      targetRow = Math.max(2, dataSheet.getLastRow() + 1);
      if (targetRow > PORTAL_CONFIG.dataRows) {
        throw new Error('Data_Source sudah mencapai batas ' + (PORTAL_CONFIG.dataRows - 1) + ' file.');
      }
    }

    if (linkMode === 'existing') {
      if (targetUrl && !isValidHttpUrl_(targetUrl)) {
        throw new Error('Tempel link lengkap yang diawali http:// atau https://.');
      }
    } else if (linkMode === 'create' && !isEdit) {
      const created = SpreadsheetApp.create(resourceName);
      targetUrl = created.getUrl();
    }

    const targetRange = dataSheet.getRange(targetRow, 1, 1, PORTAL_CONFIG.dataColumns);
    targetRange.setValues([[
      department,
      resourceName,
      description,
      targetUrl,
      status,
      ownerEmail
    ]]);

    formatDataSourceRow_(dataSheet, targetRow);
    applyDataSourceValidations_(dataSheet);
    SpreadsheetApp.flush();

    return {
      message: isEdit ? 'Dokumen berhasil diperbarui.' : 'File sudah ditambahkan ke portal.',
      url: targetUrl,
      createdSpreadsheet: linkMode === 'create' && !isEdit,
      department: getDepartmentLabel_(department)
    };
  } finally {
    lock.releaseLock();
  }
}

/**
 * Deletes a record from Data_Source sheet.
 */
function deletePortalResource(identifier) {
  const spreadsheet = getPortalSpreadsheet_();
  const lock = LockService.getScriptLock();

  if (!lock.tryLock(8000)) {
    throw new Error('Portal sedang sibuk. Coba lagi beberapa detik.');
  }

  try {
    const dataSheet = spreadsheet.getSheetByName(PORTAL_CONFIG.dataSheet);
    if (!dataSheet) {
      throw new Error('Data_Source belum tersedia.');
    }

    if (!dataSheet.getRange(1, 1).canEdit()) {
      throw new Error('Akun ini hanya memiliki akses baca. Minta akses Editor untuk menghapus file.');
    }

    const lastRow = dataSheet.getLastRow();
    if (lastRow < 2) {
      throw new Error('Tidak ada data yang dapat dihapus.');
    }

    const targetName = typeof identifier === 'object' ? String(identifier.name || '').trim() : String(identifier || '').trim();
    const targetUrl = typeof identifier === 'object' ? String(identifier.url || '').trim() : '';

    const data = dataSheet.getRange(2, 1, lastRow - 1, PORTAL_CONFIG.dataColumns).getDisplayValues();
    let rowIndexToDelete = -1;

    for (let i = 0; i < data.length; i++) {
      const rowName = String(data[i][1] || '').trim();
      const rowUrl = String(data[i][3] || '').trim();

      if (rowName === targetName && (!targetUrl || rowUrl === targetUrl)) {
        rowIndexToDelete = i + 2;
        break;
      }
    }

    if (rowIndexToDelete === -1) {
      throw new Error('File "' + targetName + '" tidak ditemukan di Data_Source.');
    }

    dataSheet.deleteRow(rowIndexToDelete);
    SpreadsheetApp.flush();

    return {
      success: true,
      message: 'File "' + targetName + '" berhasil dihapus dari portal.'
    };
  } finally {
    lock.releaseLock();
  }
}

