function prepareLauncherSheet_(spreadsheet) {
  const sheet = getOrCreateSheet_(spreadsheet, PORTAL_CONFIG.indexSheet, true);
  sheet.showSheet();

  // V3 migration: the old sheet dashboard froze A:C. HTML portal launcher
  // uses merged ranges across those columns, so remove legacy freezes first.
  sheet.setFrozenRows(0);
  sheet.setFrozenColumns(0);

  const maxRows = sheet.getMaxRows();
  const maxColumns = sheet.getMaxColumns();

  sheet.getRange(1, 1, maxRows, maxColumns).breakApart();
  sheet.clear();
  sheet.setHiddenGridlines(true);
  sheet.setTabColor('#607F89');

  if (maxColumns < 8) sheet.insertColumnsAfter(maxColumns, 8 - maxColumns);
  if (maxRows < 20) sheet.insertRowsAfter(maxRows, 20 - maxRows);

  sheet.setColumnWidths(1, 8, 86);
  sheet.setRowHeights(1, 20, 28);

  sheet.getRange('A1:H20')
    .setBackground('#EEF2F1')
    .setFontFamily('Arial')
    .setFontColor('#20282B');

  sheet.getRange('B3:G5').merge()
    .setValue('PGE Company Portal')
    .setBackground('#607F89')
    .setFontColor('#FFFFFF')
    .setFontWeight('bold')
    .setFontSize(20)
    .setHorizontalAlignment('center')
    .setVerticalAlignment('middle');

  sheet.getRange('B7:G8').merge()
    .setValue('Dashboard utama sekarang berjalan sebagai Web App.\nGoogle Sheet ini dipakai sebagai backend data.')
    .setFontColor('#697579')
    .setFontSize(10)
    .setHorizontalAlignment('center')
    .setVerticalAlignment('middle')
    .setWrap(true);

  const url = ScriptApp.getService().getUrl();
  sheet.getRange('C10:F11').merge()
    .setBackground('#FFFFFF')
    .setFontWeight('bold')
    .setFontSize(11)
    .setHorizontalAlignment('center')
    .setVerticalAlignment('middle');

  if (url) {
    const escaped = url.replace(/"/g, '""');
    sheet.getRange('C10').setFormula('=HYPERLINK("' + escaped + '","BUKA WEB PORTAL ↗")');
  } else {
    sheet.getRange('C10').setValue('DEPLOY WEB APP TERLEBIH DAHULU');
  }

  sheet.getRange('B14:G16').merge()
    .setValue('Data_Source adalah sumber data utama. Jangan menghapus atau mengubah urutan 6 kolom tanpa memperbarui Apps Script.')
    .setBackground('#FFFFFF')
    .setFontColor('#697579')
    .setFontSize(9)
    .setHorizontalAlignment('center')
    .setVerticalAlignment('middle')
    .setWrap(true);
}

function prepareDataSource_(sheet) {
  ensureSheetSize_(sheet, PORTAL_CONFIG.dataRows, PORTAL_CONFIG.dataColumns);

  const expectedHeaders = getDataSourceHeaders_();
  const currentHeaders = sheet.getRange(1, 1, 1, expectedHeaders.length)
    .getDisplayValues()[0];
  const hasAnyHeader = currentHeaders.some(Boolean);

  if (hasAnyHeader && currentHeaders.join('|') !== expectedHeaders.join('|')) {
    throw new Error(
      'Judul kolom Data_Source tidak sesuai. Urutan yang benar: ' +
      expectedHeaders.join(', ')
    );
  }

  if (!hasAnyHeader) {
    sheet.getRange(1, 1, 1, expectedHeaders.length).setValues([expectedHeaders]);
  }

  formatDataSource_(sheet);
}

function getDataSourceHeaders_() {
  return [
    'Department',
    'Resource_Name',
    'Description',
    'Target_URL',
    'Status',
    'Owner_Email'
  ];
}

function assertDataSourceSchema_(sheet) {
  const expectedHeaders = getDataSourceHeaders_();
  const currentHeaders = sheet.getRange(1, 1, 1, expectedHeaders.length)
    .getDisplayValues()[0];

  if (currentHeaders.join('|') !== expectedHeaders.join('|')) {
    throw new Error(
      'Judul kolom Data_Source tidak sesuai. Urutan yang benar: ' +
      expectedHeaders.join(', ')
    );
  }
}

function formatDataSource_(sheet) {
  const colors = PORTAL_CONFIG.colors;
  const rowCount = Math.min(
    sheet.getMaxRows(),
    Math.max(PORTAL_CONFIG.dataFormatRows, sheet.getLastRow())
  );

  sheet.setHiddenGridlines(true);
  // Data_Source should never have frozen columns. Legacy/manual frozen columns
  // can conflict with merged cells/protections and trigger a Sheets exception.
  sheet.setFrozenColumns(0);
  sheet.setFrozenRows(1);
  sheet.setTabColor(colors.accentDark);

  sheet.getRange(1, 1, rowCount, PORTAL_CONFIG.dataColumns)
    .setFontFamily('Arial')
    .setFontSize(10)
    .setFontColor(colors.text)
    .setVerticalAlignment('middle');

  sheet.getRange(1, 1, 1, PORTAL_CONFIG.dataColumns)
    .setBackground(colors.accentDark)
    .setFontColor('#FFFFFF')
    .setFontWeight('bold');

  if (rowCount > 1) {
    sheet.getRange(2, 1, rowCount - 1, PORTAL_CONFIG.dataColumns)
      .setBackground(colors.surface)
      .setBorder(true, true, true, true, true, true, colors.border, SpreadsheetApp.BorderStyle.SOLID);
  }

  sheet.setRowHeight(1, 40);
  if (rowCount > 1) sheet.setRowHeights(2, rowCount - 1, 34);

  [150, 250, 390, 320, 120, 250].forEach((width, index) => {
    sheet.setColumnWidth(index + 1, width);
  });

  applyDataSourceValidations_(sheet);
  if (rowCount > 1) {
    sheet.getRange(2, 3, rowCount - 1, 1).setWrap(true);
    sheet.getRange(2, 4, rowCount - 1, 1).setNumberFormat('@');
  }

  const filter = sheet.getFilter();
  if (filter) filter.remove();
  sheet.getRange(1, 1, sheet.getMaxRows(), PORTAL_CONFIG.dataColumns).createFilter();

  if (rowCount > 1) {
    sheet.setConditionalFormatRules(createStatusRules_(
      sheet.getRange(2, 5, rowCount - 1, 1)
    ));
  }
}

function formatDataSourceRow_(sheet, row) {
  const colors = PORTAL_CONFIG.colors;

  sheet.getRange(row, 1, 1, PORTAL_CONFIG.dataColumns)
    .setBackground(colors.surface)
    .setFontFamily('Arial')
    .setFontSize(10)
    .setFontColor(colors.text)
    .setVerticalAlignment('middle')
    .setBorder(true, true, true, true, true, true, colors.border, SpreadsheetApp.BorderStyle.SOLID);

  sheet.getRange(row, 3).setWrap(true);
  sheet.getRange(row, 4).setNumberFormat('@');
  sheet.setRowHeight(row, 34);

  const statusRange = sheet.getRange(2, 5, Math.max(1, sheet.getLastRow() - 1), 1);
  sheet.setConditionalFormatRules(createStatusRules_(statusRange));
}

function applyDataSourceValidations_(sheet) {
  const rowCount = Math.min(
    sheet.getMaxRows(),
    Math.max(PORTAL_CONFIG.dataFormatRows, sheet.getLastRow())
  );
  if (rowCount < 2) return;

  const departmentRule = SpreadsheetApp.newDataValidation()
    .requireValueInList(getDepartmentValues_(sheet).filter(value => value !== 'All'), true)
    .setAllowInvalid(true)
    .build();

  const statusRule = SpreadsheetApp.newDataValidation()
    .requireValueInList(PORTAL_CONFIG.statuses.slice(1), true)
    .setAllowInvalid(false)
    .build();

  const emailRule = SpreadsheetApp.newDataValidation()
    .requireTextIsEmail()
    .setAllowInvalid(false)
    .build();

  sheet.getRange(2, 1, rowCount - 1, 1).setDataValidation(departmentRule);
  sheet.getRange(2, 5, rowCount - 1, 1).setDataValidation(statusRule);
  sheet.getRange(2, 6, rowCount - 1, 1).setDataValidation(emailRule);
}

function getPortalRecords_(sheet) {
  const lastRow = Math.min(sheet.getLastRow(), PORTAL_CONFIG.dataRows);
  if (lastRow < 2) return [];

  return sheet.getRange(2, 1, lastRow - 1, PORTAL_CONFIG.dataColumns)
    .getDisplayValues()
    .filter(row => String(row[1] || '').trim())
    .map((row, index) => ({
      id: index + 2,
      department: String(row[0] || '').trim() || 'All',
      name: String(row[1] || '').trim(),
      description: String(row[2] || '').trim(),
      url: String(row[3] || '').trim(),
      status: String(row[4] || '').trim(),
      owner: String(row[5] || '').trim()
    }));
}

function compareRecords_(a, b) {
  const statusOrder = {Active: 1, Pending: 2, Archived: 3};
  const difference = (statusOrder[a.status] || 9) - (statusOrder[b.status] || 9);
  if (difference !== 0) return difference;
  return a.name.localeCompare(b.name);
}

function buildStatsPayload_(records, departments) {
  return {
    total: records.length,
    active: records.filter(record => record.status === 'Active').length,
    pending: records.filter(record => record.status === 'Pending').length,
    archived: records.filter(record => record.status === 'Archived').length,
    departments: departments.filter(value => value !== 'All').length
  };
}

function getDepartmentValues_(dataSheet) {
  const departments = [];
  const seen = new Set();

  function addDepartment(value) {
    const department = String(value || '').trim();
    const key = department.toLowerCase();
    if (!department || department === 'All' || seen.has(key)) return;
    seen.add(key);
    departments.push(department);
  }

  PORTAL_CONFIG.departments.filter(value => value !== 'All').forEach(addDepartment);

  if (dataSheet && dataSheet.getLastRow() >= 2) {
    dataSheet.getRange(2, 1, dataSheet.getLastRow() - 1, 1)
      .getDisplayValues()
      .flat()
      .forEach(addDepartment);
  }

  return ['All'].concat(departments);
}

function getDepartmentLabel_(department) {
  return PORTAL_CONFIG.departmentLabels[department] || department;
}

function getStatusLabel_(status) {
  return PORTAL_CONFIG.statusLabels[status] || status;
}

function createStatusRules_(range) {
  const colors = PORTAL_CONFIG.colors;
  return [
    SpreadsheetApp.newConditionalFormatRule()
      .whenTextEqualTo('Active')
      .setFontColor(colors.successText)
      .setBackground(colors.successBackground)
      .setRanges([range])
      .build(),
    SpreadsheetApp.newConditionalFormatRule()
      .whenTextEqualTo('Pending')
      .setFontColor(colors.pendingText)
      .setBackground(colors.pendingBackground)
      .setRanges([range])
      .build(),
    SpreadsheetApp.newConditionalFormatRule()
      .whenTextEqualTo('Archived')
      .setFontColor(colors.archivedText)
      .setBackground(colors.archivedBackground)
      .setRanges([range])
      .build()
  ];
}

function showDataSource() {
  const spreadsheet = getPortalSpreadsheet_();
  const sheet = spreadsheet.getSheetByName(PORTAL_CONFIG.dataSheet);
  if (!sheet) throw new Error('Data_Source belum tersedia.');
  sheet.showSheet();

  const activeSpreadsheet = SpreadsheetApp.getActiveSpreadsheet();
  if (activeSpreadsheet && activeSpreadsheet.getId() === spreadsheet.getId()) {
    sheet.activate();
  }
}

function hideDataSource() {
  const spreadsheet = getPortalSpreadsheet_();
  const dataSheet = spreadsheet.getSheetByName(PORTAL_CONFIG.dataSheet);
  const indexSheet = spreadsheet.getSheetByName(PORTAL_CONFIG.indexSheet);
  if (!dataSheet || !indexSheet) throw new Error('Portal belum disiapkan.');
  indexSheet.showSheet();
  dataSheet.hideSheet();
}

function enablePortalProtection() {
  const spreadsheet = getPortalSpreadsheet_();
  const dataSheet = spreadsheet.getSheetByName(PORTAL_CONFIG.dataSheet);
  if (!dataSheet) throw new Error('Data_Source belum tersedia.');
  applyPortalProtections_(dataSheet);
}

function disablePortalProtection() {
  const spreadsheet = getPortalSpreadsheet_();
  const dataSheet = spreadsheet.getSheetByName(PORTAL_CONFIG.dataSheet);
  if (!dataSheet) throw new Error('Data_Source belum tersedia.');
  removePortalProtections_(dataSheet);
}

function applyPortalProtections_(dataSheet) {
  removePortalProtections_(dataSheet);
  dataSheet.protect()
    .setDescription(PORTAL_CONFIG.protectionPrefix + 'Data_Source')
    .setWarningOnly(true);
}

function removePortalProtections_(dataSheet) {
  // Normalize legacy frozen-column state before asking Sheets for protection
  // metadata. This specifically fixes the migration error:
  // 'You cannot merge frozen columns with non-frozen columns.'
  try {
    dataSheet.setFrozenColumns(0);
  } catch (error) {
    console.warn('Tidak dapat mereset kolom beku Data_Source: ' + error.message);
  }

  SpreadsheetApp.flush();

  try {
    dataSheet.getProtections(SpreadsheetApp.ProtectionType.SHEET)
      .filter(protection =>
        String(protection.getDescription() || '').startsWith(PORTAL_CONFIG.protectionPrefix)
      )
      .forEach(protection => protection.remove());
  } catch (error) {
    // Protection here is warning-only, not a security boundary. Do not block
    // portal setup if a legacy Sheets protection object is malformed.
    console.warn('Proteksi lama tidak dapat dibersihkan: ' + error.message);
  }
}

function getPortalSpreadsheet_() {
  const propertyStore = PropertiesService.getScriptProperties();
  let spreadsheetId = propertyStore.getProperty(PORTAL_CONFIG.spreadsheetProperty);

  if (!spreadsheetId) {
    const active = SpreadsheetApp.getActiveSpreadsheet();
    if (active) {
      spreadsheetId = active.getId();
      propertyStore.setProperty(PORTAL_CONFIG.spreadsheetProperty, spreadsheetId);
    }
  }

  if (!spreadsheetId) {
    throw new Error('Spreadsheet portal belum terhubung. Jalankan setupWebPortal() sekali dari spreadsheet.');
  }

  return SpreadsheetApp.openById(spreadsheetId);
}

function getOrCreateSheet_(spreadsheet, sheetName, reuseBlankSheet) {
  const existing = spreadsheet.getSheetByName(sheetName);
  if (existing) return existing;

  if (reuseBlankSheet && spreadsheet.getSheets().length === 1) {
    const onlySheet = spreadsheet.getSheets()[0];
    if (!hasContent_(onlySheet)) {
      onlySheet.setName(sheetName);
      return onlySheet;
    }
  }

  return spreadsheet.insertSheet(sheetName);
}

function ensureSheetSize_(sheet, targetRows, targetColumns) {
  const currentRows = sheet.getMaxRows();
  const currentColumns = sheet.getMaxColumns();

  if (currentRows < targetRows) {
    sheet.insertRowsAfter(currentRows, targetRows - currentRows);
  }
  if (currentColumns < targetColumns) {
    sheet.insertColumnsAfter(currentColumns, targetColumns - currentColumns);
  }
}

function normalizeUrl_(value) {
  return String(value || '')
    .trim()
    .replace(/#.*$/, '')
    .replace(/\/$/, '')
    .toLowerCase();
}

function isValidHttpUrl_(value) {
  return /^https?:\/\//i.test(String(value || '').trim());
}

function escapeHtml_(value) {
  return String(value || '')
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#39;');
}

function hasContent_(sheet) {
  return sheet.getLastRow() > 0 || sheet.getLastColumn() > 0;
}
